#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    char *A = (char *) a;
    char *B = (char *) b;

    char abbr1[3];
    strncpy(abbr1, A, 2);
    char num1[5];
    strncpy(num1, A+2, 4);

    char abbr2[3];
    strncpy(abbr2, B, 2);
    char num2[5];
    strncpy(num2, B+2, 4);

    int res = strcmp(abbr1, abbr2);
    if(res == 0) {
        return strcmp(num1, num2);
    } else {
        return res;
    }
}

int main() {
    char s[1000];
    gets(s);

    char flights[100][7];
    int flights_size = 0;

    char *token = strtok(s, ",");
    while (token != NULL) {
        strcpy(flights[flights_size++], token);
        token = strtok(NULL, ",");
    }

    qsort(flights, flights_size, sizeof(flights[0]), cmp);

    for (int i = 0; i < flights_size; i++) {
        printf("%s", flights[i]);
        if (i != flights_size - 1) {
            printf(",");
        }
    }
}
